import{_ as o,a0 as p,w as r,s as d,ao as l,I as a,x as e,a1 as s,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 CentOS、RHEL、Rocky Linux 最小化安裝中設置互聯網 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS、RHEL、Rocky Linux 最小化安裝中設置互聯網 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS、RHEL、Rocky Linux 最小化安裝中設置互聯網 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS、RHEL、Rocky Linux 最小化安裝中設置互聯網 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210625 How to Setup Internet in CentOS, RHEL, Rocky Linux Minimal Install","title":"如何在 CentOS、RHEL、Rocky Linux 最小化安裝中設置互聯網","tag":"202107","desc":""},"relativePath":"202107/20210625 How to Setup Internet in CentOS, RHEL, Rocky Linux Minimal Install.md","filePath":"[post].md"}'),u={name:"202107/20210625 How to Setup Internet in CentOS, RHEL, Rocky Linux Minimal Install.md"};function g(k,t,h,c,m,b){const i=p("Link");return r(),d("div",null,[t[23]||(t[23]=l('<h1 id="如何在-centos、rhel、rocky-linux-最小化安裝中設置互聯網" tabindex="-1">如何在 CentOS、RHEL、Rocky Linux 最小化安裝中設置互聯網 <a class="header-anchor" href="#如何在-centos、rhel、rocky-linux-最小化安裝中設置互聯網" aria-label="Permalink to “如何在 CentOS、RHEL、Rocky Linux 最小化安裝中設置互聯網”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202107/16/104745wne0x111onmafxj9.jpg" alt=""></p><p>在最小化服務器安裝中，設置互聯網或網絡是非常容易的。在本指南中，我們將解釋如何在 CentOS、RHEL、Rocky Linux 最小安裝中設置互聯網或網絡。</p><p>當你剛剛完成任何服務器發行版的最小化安裝時，你沒有任何圖形界面或桌面環境可以用於設置你的網絡或互聯網。因此，當你只能使用終端時，瞭解如何設置聯網是很重要的。NetworkManager 以及 systemd 服務為完成這項工作提供了必要的工具。以下是具體使用方法。</p><h3 id="在-centos、rhel、rocky-linux-最小化安裝中設置互聯網" tabindex="-1">在 CentOS、RHEL、Rocky Linux 最小化安裝中設置互聯網 <a class="header-anchor" href="#在-centos、rhel、rocky-linux-最小化安裝中設置互聯網" aria-label="Permalink to “在 CentOS、RHEL、Rocky Linux 最小化安裝中設置互聯網”">​</a></h3><p>完成安裝後，啓動服務器終端。理想情況下，你應該會看到提示符。使用 root 或 admin 賬户登錄。</p><p>然後，首先嚐試使用 <code>nmcli</code> 檢查網絡接口的狀態和細節。<code>nmcli</code> 是一個控制 NetworkManager 服務的命令列工具。使用以下命令進行檢查。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nmcli device status</span></span></code></pre></div><p>這將顯示設備名稱、狀態等。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/nmcli-device-status.jpg" alt="nmcli device status"></p>',10)),a("p",null,[t[1]||(t[1]=e("運行工具 ",-1)),t[2]||(t[2]=a("code",null,"nmtui",-1)),t[3]||(t[3]=e(" 來配置網絡接口。",-1)),s(i,{href:"https://access.redhat.com/documentation/en-us/red_hat_enterprise_linux/7/html/networking_guide/sec-configuring_ip_networking_with_nmtui"},{default:n(()=>[...t[0]||(t[0]=[e("nmtui",-1)])]),_:1}),t[4]||(t[4]=e(" 是 NetworkManager 工具的一部分，它為你提供了一個漂亮的用户界面來配置網絡。這是 NetworkManager-tui 包的一部分，當你完成最小服務器的安裝時它應該默認安裝。",-1))]),t[24]||(t[24]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nmtui</span></span></code></pre></div><p>在 <code>nmtui</code> 窗口中點擊編輯一個連接。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/nmtui-Select-options.jpg" alt="nmtui – Select options"></p><p>選擇網口名稱：</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/Select-Interface-to-Edit.jpg" alt="Select Interface to Edit"></p><p>在編輯連接窗口，為 IPv4 和 IPv6 選擇自動。並選擇自動連接。完成後按 “OK”。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/nmtui-Edit-Connection.jpg" alt="nmtui – Edit Connection"></p>',7)),a("p",null,[t[6]||(t[6]=e("通過使用如下 ",-1)),s(i,{href:"https://www.debugpoint.com/2020/12/systemd-systemctl-service/"},{default:n(()=>[...t[5]||(t[5]=[e("systemd systemctl",-1)])]),_:1}),t[7]||(t[7]=e(" 命令，重新啓動 NetworkManager 服務。",-1))]),t[25]||(t[25]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl restart NetworkManager</span></span></code></pre></div><p>如果一切順利，在 CentOS、RHEL、Rocky Linux 服務器的最小化安裝中你應該可以連接到網絡和互聯網了，前提是你的網絡有互聯網連接。你可以用 <code>ping</code> 來驗證它是否正常。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/setup-internet-minimal-server-CentOS-Rocky-Linux-RHEL.jpg" alt="setup internet minimal server – CentOS Rocky Linux RHEL"></p><h3 id="額外技巧-在最小化服務器中設置靜態-ip" tabindex="-1">額外技巧：在最小化服務器中設置靜態 IP <a class="header-anchor" href="#額外技巧-在最小化服務器中設置靜態-ip" aria-label="Permalink to “額外技巧：在最小化服務器中設置靜態 IP”">​</a></h3><p>當你把網絡配置設置為自動，當你連接到互聯網時，網口會動態地分配 IP。在某些情況下，當你建立一個局域網 （LAN） 時，你可能想給你的網口分配靜態 IP。這超級簡單。</p><p>打開你的網絡的網絡配置腳本。根據你的設備修改高亮部分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /etc/sysconfig/network-scripts/ifcfg-ens3</span></span></code></pre></div><p>在上面的文件中，用 <code>IPADDR</code> 屬性添加你想要的 IP 地址。保存該文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>IPADDR=192.168.0.55</span></span></code></pre></div><p>在 <code>/etc/sysconfig/network</code> 中為你的網絡添加網關：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NETWORKING=yes</span></span>
<span class="line"><span>HOSTNAME=debugpoint</span></span>
<span class="line"><span>GATEWAY=10.1.1.1</span></span></code></pre></div><p>在 <code>/etc/resolv.conf</code> 的 <code>resolv.conf</code> 中添加任意公共 DNS 服務器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nameserver 8.8.8.8</span></span>
<span class="line"><span>nameserver 8.8.4.4</span></span></code></pre></div><p>並重新啓動網絡服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl restart NetworkManager</span></span></code></pre></div><p>這樣就完成了靜態 IP 的設置。你也可以使用 <code>ip addr</code> 命令檢查詳細的 IP 信息。</p><p>我希望這個指南能幫助你在你的最小化服務器中設置網絡、互聯網和靜態 IP。如果你有任何問題，請在評論區告訴我。</p><hr>`,18)),a("p",null,[t[9]||(t[9]=e("via: ",-1)),s(i,{href:"https://www.debugpoint.com/2021/06/setup-internet-minimal-install-server/"},{default:n(()=>[...t[8]||(t[8]=[e("https://www.debugpoint.com/2021/06/setup-internet-minimal-install-server/",-1)])]),_:1})]),a("p",null,[t[14]||(t[14]=e("作者：",-1)),s(i,{href:"https://www.debugpoint.com/author/admin1/"},{default:n(()=>[...t[10]||(t[10]=[e("Arindam",-1)])]),_:1}),t[15]||(t[15]=e(" 選題：",-1)),s(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[11]||(t[11]=[e("lujun9972",-1)])]),_:1}),t[16]||(t[16]=e(" 譯者：",-1)),s(i,{href:"https://github.com/geekpi"},{default:n(()=>[...t[12]||(t[12]=[e("geekpi",-1)])]),_:1}),t[17]||(t[17]=e(" 校對：",-1)),s(i,{href:"https://github.com/turbokernel"},{default:n(()=>[...t[13]||(t[13]=[e("turbokernel",-1)])]),_:1})]),a("p",null,[t[20]||(t[20]=e("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[18]||(t[18]=[e("LCTT",-1)])]),_:1}),t[21]||(t[21]=e(" 原創編譯，",-1)),s(i,{href:"https://linux.cn/"},{default:n(()=>[...t[19]||(t[19]=[e("Linux中國",-1)])]),_:1}),t[22]||(t[22]=e(" 榮譽推出",-1))])])}const w=o(u,[["render",g]]);export{C as __pageData,w as default};
